package m8

import "net/http"

func (h *Hub) HandleTemplatePage(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.Write([]byte(pilotTemplateHTML))
}

const pilotTemplateHTML = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PRD 到 spec</title>
<style>body{font:16px system-ui;background:#f4f6fa;color:#20324b;max-width:1100px;margin:24px auto;padding:0 16px}section,article{background:white;border:1px solid #cdd7e6;padding:20px;margin:16px 0;border-radius:10px}label{display:block;margin:12px 0}input,textarea,select,button{min-height:44px;max-width:100%;font:inherit;box-sizing:border-box;padding:8px;border:1px solid #a9b8cc;border-radius:5px}input,textarea{width:100%}textarea{min-height:85px}button{cursor:pointer;margin:4px;background:#eaf1fc}pre{white-space:pre-wrap;overflow-wrap:anywhere}.row{display:flex;gap:12px;flex-wrap:wrap}.row label{flex:1;min-width:200px}.muted,small{color:#536781}[hidden]{display:none!important}.entry{border:1px solid #d8dfea;padding:14px;margin:12px 0}h1{font-size:26px}h2{font-size:21px}body{overflow-wrap:anywhere}@media(max-width:600px){a,summary{display:inline-flex;align-items:center;min-height:44px}section,article{padding:12px}.row label{min-width:0;flex-basis:100%}}</style>
<header><a href="/console">Console</a> · <a href="/console/questions">研发问题</a><h1>PRD → 可确认 spec</h1><p>默认轻量：补六项、本人接受责任、独立 Agent 复核、人类确认。确认草稿不会执行任务或代表业务签收。</p><p id="risk-guidance">「未评估」不等于「无风险」。涉及真实生产或安全面须升级完整档并独立核验。</p></header><p id="status" role="status"></p>
<section><h2>待完善与责任邀请</h2><div id="draft-list"></div><button id="more" hidden>下一页</button><button id="fresh">新建草稿</button></section>
<section><h2>1. 贴来源，选本次范围</h2><label>飞书 PRD 链接<input id="source-url" type="url" placeholder="https://租户.feishu.cn/docx/文档ID"></label><label>导入方式<select id="source-mode"><option value="connector">请求连接器导入（未配置时明确待配置）</option><option value="manual_export">本人有权导出的原文</option></select></label><div id="export-fields" hidden><label>原文版本或导出时间<input id="source-revision"></label><label>原文（须包含逐字 owner_ref）<textarea id="source-content"></textarea></label></div><button id="save-source">保存来源快照</button><pre id="source-summary"></pre>
<div class="row"><label>名称<input id="title"></label><label>形态<select id="kind"><option value="parent">父 spec</option><option value="child">所选范围子 spec</option></select></label><label>团队<select id="team"><option value="single">单人＋独立审查 Agent</option><option value="multi">多人</option></select></label></div><label>目标<textarea id="goal"></textarea></label><label>本次明确范围（不会自动扩为全部范围）<textarea id="scope"></textarea></label><label id="parent-field" hidden>已定稿模板父 spec<select id="parent"><option value="">先完成并定稿父 spec</option></select></label>
<details><summary>新修订／已定稿的后继</summary><p>未定稿用原 spec 的新修订；已定稿保持原文不变，生成 derived successor，并阻断原范围任务等待变更处理。</p><label>目标 spec ID<input id="target"></label><label>目标当前修订<input id="target-revision" type="number" min="1"></label><label><input id="predecessor" type="checkbox" style="width:auto">此目标已定稿，生成后继</label><label>变更原因<textarea id="change-reason"></textarea></label><label>完整档降档原因<input id="downgrade-reason"></label><label>风险解除证据<input id="risk-clearance"></label></details></section>
<section><h2>2. 补齐每条六项</h2><p>共用值会逐条展开；单项可覆盖。unknown／未认领不算完整。角色接受只表示承担责任，未产生测试通过或签收。</p><div id="defaults"></div><button id="add-entry">增加需求／子例</button><button id="stock">载入 STOCK 13 例样板（不是选择首试或执行）</button><div id="entries"></div><datalist id="principals"></datalist>
<details id="full-details"><summary>完整档附加（真实生产／安全面自动升级）</summary><label>档位<select id="mode"><option value="light">轻量</option><option value="full">完整</option></select></label><label><input id="production" type="checkbox" style="width:auto">涉及真实生产动作</label><label><input id="security" type="checkbox" style="width:auto">涉及安全面</label><p>轻量附加字段可不填；「未评估」不等于「无风险」，也不写成安全。完整档须补七属性、规则、六面、人审与具体授权，不能手动降档绕过。</p><div id="full-fields"></div><label>七属性（JSON 对象）<textarea id="attributes">{}</textarea></label><label>六面（JSON 对象）<textarea id="faces">{}</textarea></label><label>rule_ids（逗号分隔）<input id="rule-ids"></label><label><input id="auth-none" type="checkbox" style="width:auto">本版无真实动作预授权（生产动作不能选）</label></details>
<button id="save-draft">保存并检查本版</button><pre id="missing"></pre></section>
<section><h2>3. 核对并确认本版</h2><div id="roles"></div><label>责任撤回／完整档人审说明<input id="receipt-reason"></label><pre id="preview"></pre><label><input id="confirm-human" type="checkbox" style="width:auto">本人已确认来源、范围和本版责任；确认仅创建待预审 spec</label><button id="confirm">确认本版草稿</button><div id="confirmed"></div><h3>Spec Kit 本版产物（不含执行结果）</h3><div id="artifacts"></div></section>
<script>
'use strict';const $=x=>document.getElementById(x),fields=[['acceptance','验收标准'],['test_method','测试方法'],['deliverable','交付物'],['environment','环境'],['executor','执行人'],['reviewer','复核人／审查 Agent'],['signoff','人类签收责任人']],fullFields=[['analyze_reference','analyze 证据'],['deliverable_contract_reference','交付合同'],['probes_reference','探针／证据'],['rule_version','规则表版本'],['authorization_reference','具体授权出处'],['authorization_scope','授权范围'],['authorization_purpose','目的'],['authorization_expires_at','到期 UTC（RFC3339）'],['review_principal','完整档人审 user:ID'],['review_reference','人审记录']];let source=null,current=null,entries=[],after='',nextAfter='',sample=null,dirty=false,writes=new Map(),options={};
function message(t){$('status').textContent=t}function clearPrivate(){current=null;source=null;entries=[];options={};writes.clear();after=nextAfter='';for(const el of document.querySelectorAll('input,textarea')){el.value='';if(el.type==='checkbox')el.checked=false}for(const el of document.querySelectorAll('select'))el.selectedIndex=0;$('source-summary').textContent='';$('principals').replaceChildren();$('parent').replaceChildren();$('entries').replaceChildren();$('preview').textContent='';$('roles').replaceChildren();$('missing').textContent='';$('draft-list').replaceChildren();$('source-content').value='';$('confirmed').replaceChildren();$('artifacts').replaceChildren()}
async function api(path,opt={}){const r=await fetch(path,{credentials:'same-origin',...opt,headers:{'Content-Type':'application/json'}});const b=await r.json();if(!r.ok){if(r.status===401||r.status===403)clearPrivate();throw Error(r.status===409?'本版已变化或门未满足，请重新读取；不自动重试。':r.status+' 请求拒绝')}return b}
async function write(key,path,body){const prior=writes.get(key);const raw=JSON.stringify(body);if(prior&&prior.raw!==raw)throw Error('上次写入结果未知，须先读取核对再修改。');const job=prior||{raw,request_id:crypto.randomUUID()};writes.set(key,job);try{const b=await api(path,{method:'POST',body:JSON.stringify({...body,request_id:job.request_id})});writes.delete(key);return b}catch(e){message('未确认写入结果；保留本次请求号，核对后重试相同内容。');throw e}}
function input(parent,id,label,value='',list=false){const l=document.createElement('label');l.textContent=label;const x=document.createElement('input');x.id=id;x.value=value;if(list)x.setAttribute('list','principals');l.append(x);parent.append(l);return x}
for(const [key,label]of fields)input($('defaults'),'default-'+key,label+'（共用）','',key==='executor'||key==='reviewer'||key==='signoff');for(const [key,label]of fullFields)input($('full-fields'),'full-'+key,label);
function drawEntries(){const root=$('entries');root.replaceChildren();entries.forEach((e,i)=>{const a=document.createElement('article');a.className='entry';input(a,'entry-'+i+'-id','稳定 ID',e.id||'');const k=document.createElement('select');k.id='entry-'+i+'-kind';for(const v of ['requirement','case']){const o=document.createElement('option');o.value=v;o.textContent=v==='requirement'?'需求':'子例';k.append(o)}k.value=e.kind||'requirement';a.append(k);input(a,'entry-'+i+'-title','名称',e.title||'');input(a,'entry-'+i+'-owner_ref','原文逐字引句',e.owner_ref||'');for(const [key,label]of fields)input(a,'entry-'+i+'-'+key,label+'（空白继承）',e.fields?.[key]||'',key==='executor'||key==='reviewer'||key==='signoff');input(a,'entry-'+i+'-budget','业务写上限（不是授权）',String(e.business_write_limit||0));const remove=document.createElement('button');remove.textContent='移除此条';remove.onclick=()=>{readEntries();entries.splice(i,1);drawEntries();dirty=true};a.append(remove);root.append(a)})}
function readEntries(){entries=entries.map((e,i)=>({...e,id:$('entry-'+i+'-id').value,kind:$('entry-'+i+'-kind').value,title:$('entry-'+i+'-title').value,owner_ref:$('entry-'+i+'-owner_ref').value,business_write_limit:Number($('entry-'+i+'-budget').value),fields:Object.fromEntries(fields.map(([k])=>[k,$('entry-'+i+'-'+k).value]))}))}
function documentValue(){readEntries();const parent=$('parent').selectedOptions[0]?.dataset.ref;const d={template_version:options.template_version,kind:$('kind').value,title:$('title').value,goal:$('goal').value,scope:$('scope').value,team_mode:$('team').value,source_id:source?.id||'',risk_assessment:current?.document?.risk_assessment||'unassessed',requested_mode:$('mode').value,production:$('production').checked,security:$('security').checked,defaults:Object.fromEntries(fields.map(([k])=>[k,$('default-'+k).value])),entries,full:{...Object.fromEntries(fullFields.map(([k])=>[k,$('full-'+k).value])),attributes:JSON.parse($('attributes').value),content_faces:JSON.parse($('faces').value),rule_ids:$('rule-ids').value.split(',').map(x=>x.trim()).filter(Boolean),authorization_none:$('auth-none').checked},sample:current?.document?.sample||''};if(d.kind==='child'&&parent)d.parent=JSON.parse(parent);if($('target').value){d[$('predecessor').checked?'predecessor_spec_id':'target_spec_id']=$('target').value;d.expected_revision=Number($('target-revision').value);d.change_reason=$('change-reason').value}d.downgrade_reason=$('downgrade-reason').value;d.risk_clearance_reference=$('risk-clearance').value;return d}
function fill(v){current=v;source=v.source;const d=v.document;for(const k of ['title','goal','scope','kind'])$(k).value=d[k]||'';$('team').value=d.team_mode;$('mode').value=d.requested_mode;$('production').checked=d.production;$('security').checked=d.security;for(const [k]of fields)$('default-'+k).value=d.defaults[k]||'';entries=structuredClone(d.entries);drawEntries();for(const [k]of fullFields)$('full-'+k).value=d.full[k]||'';$('attributes').value=JSON.stringify(d.full.attributes||{});$('faces').value=JSON.stringify(d.full.content_faces||{});$('rule-ids').value=(d.full.rule_ids||[]).join(',');$('auth-none').checked=d.full.authorization_none;$('target').value=d.target_spec_id||d.predecessor_spec_id||'';$('predecessor').checked=!!d.predecessor_spec_id;$('target-revision').value=d.expected_revision||'';$('change-reason').value=d.change_reason||'';$('downgrade-reason').value=d.downgrade_reason||'';$('risk-clearance').value=d.risk_clearance_reference||'';$('parent-field').hidden=d.kind!=='child';if(d.parent)$('parent').value=d.parent.spec_id;$('source-summary').textContent=source.source_kind+' · '+source.state+' · SHA '+source.content_sha256;$('source-url').value=source.source_url;renderView(v);dirty=false}
function renderView(v){$('missing').textContent=v.missing.length?v.missing.map(x=>x.path+'：'+x.reason).join('\n'):'结构与责任齐备；尚未执行或签收';$('preview').textContent=v.content_markdown||'';$('confirm').disabled=!v.can_confirm;$('roles').replaceChildren();for(const role of v.roles){const div=document.createElement('div');div.textContent=role.entry_id+' / '+role.role+' / '+role.principal+'：'+(role.accepted?'已本人接受责任':'未接受责任');for(const decision of (role.principal===options.actor_principal?['accepted','withdrawn']:[])){const b=document.createElement('button');b.textContent=decision==='accepted'?'本人接受此责任':'本人撤回';b.onclick=()=>receipt(role,decision).catch(e=>message(e.message));div.append(b)}$('roles').append(div)}$('confirmed').replaceChildren();if(v.spec_id){const a=document.createElement('a');a.href='/console/specs/'+encodeURIComponent(v.spec_id);a.textContent='打开 spec 第 '+v.spec_revision+' 版，继续真实 Agent 预审与人类定稿';$('confirmed').append(a);if(v.impact){const p=document.createElement('p');p.textContent='影响：原 spec '+v.impact.predecessor_spec_id+' r'+v.impact.predecessor_revision+' 的 '+v.impact.task_count+' 条任务已阻断，未迁移或自动重派。首 '+v.impact.limit+' 项：'+v.impact.task_ids.join('、');$('confirmed').append(p)}}$('artifacts').replaceChildren();for(const [name,body]of Object.entries(v.artifacts||{})){const b=document.createElement('button');b.textContent='查看 '+name;b.onclick=()=>{$('preview').textContent=body};$('artifacts').append(b)}}
async function read(id){const b=await api('/api/console/spec-templates/'+encodeURIComponent(id));fill({...b.draft,artifacts:b.artifacts||{}});writes.clear();message('已读取本版；修改会生成新版本，旧责任不自动继承。')}
async function receipt(role,decision){if(!current)return;if(dirty)throw Error('先保存并读取本版，再接受或撤回责任。');const b=await write('receipt:'+current.draft_id+':'+role.entry_id+role.role,'/api/console/spec-templates/'+encodeURIComponent(current.draft_id),{operation:'responsibility',expected_version:current.version,plan_sha256:current.plan_sha256,entry_ids:[role.entry_id],role:role.role,decision,reason:$('receipt-reason').value,confirm_human:role.role==='full_review'});fill({...b.draft,artifacts:b.artifacts||{}});message('已记录本人责任决定；不代表执行、测试通过或业务签收。')}
async function list(){const b=await api('/api/console/spec-templates'+(after?'?after='+encodeURIComponent(after):''));nextAfter=b.next_after||'';$('more').hidden=!nextAfter;$('draft-list').replaceChildren();for(const d of b.drafts){const b=document.createElement('button');b.textContent=d.document.title+' · v'+d.version+' · '+d.state;b.onclick=()=>{if(dirty&&!window.confirm('放弃未保存输入并读取本版？'))return;read(d.draft_id).catch(e=>message(e.message))};$('draft-list').append(b)}}
$('source-mode').onchange=()=>{$('export-fields').hidden=$('source-mode').value!=='manual_export'};$('kind').onchange=()=>{$('parent-field').hidden=$('kind').value!=='child';dirty=true};$('add-entry').onclick=()=>{readEntries();entries.push({kind:'requirement',fields:{}});drawEntries();dirty=true};$('stock').onclick=()=>{if(entries.length&&!window.confirm('用原 13 例样板替换未保存条目？'))return;entries=structuredClone(sample.entries);current={...current,document:{...current?.document,sample:'stock13'}};$('kind').value='child';$('parent-field').hidden=false;drawEntries();dirty=true;message('13 例全部 NOT_RUN；预算不是授权，未选择真实首试范围。')};$('fresh').onclick=()=>{if(dirty&&!window.confirm('放弃未保存输入？'))return;location.href='/console/spec-templates'};
$('save-source').onclick=async()=>{try{const b=await write('source','/api/console/spec-template-sources',{source_url:$('source-url').value,mode:$('source-mode').value,source_revision:$('source-mode').value==='manual_export'?$('source-revision').value:'',content_markdown:$('source-mode').value==='manual_export'?$('source-content').value:''});source=b.source;$('source-summary').textContent=source.state+' · '+source.source_kind+' · '+source.content_sha256;dirty=true;message(source.state==='ready'?'来源快照已固定；继续补六项。':'连接器未配置；可改用本人有权导出的原文，不借凭据。')}catch(e){message(e.message)}};
$('save-draft').onclick=async()=>{try{if(current?.state==='confirmed')throw Error('已确认本版不可改写；请新建草稿并指定原 spec／后继。');const b=await write('save:'+current?.draft_id,'/api/console/spec-templates'+(current?.draft_id?'/'+encodeURIComponent(current.draft_id):''),{operation:'save',expected_version:current?.version||0,document:documentValue()});fill({...b.draft,artifacts:b.artifacts||{}});await list();message('已保存待完善版本；每条缺项与本人责任已列出。')}catch(e){message(e.message)}};
$('confirm').onclick=async()=>{try{if(!current||dirty)throw Error('先保存并读取当前版本，再确认。');if(!$('confirm-human').checked)throw Error('须本人勾选确认。');const b=await write('confirm:'+current.draft_id,'/api/console/spec-templates/'+encodeURIComponent(current.draft_id),{operation:'confirm',expected_version:current.version,plan_sha256:current.plan_sha256,confirm_human:true});fill({...b.draft,artifacts:b.artifacts||{}});await list();message('只生成待预审 spec；没有执行、授权或业务签收。')}catch(e){message(e.message)}};$('more').onclick=()=>{after=nextAfter;list().catch(e=>message(e.message))};document.addEventListener('input',e=>{if(e.target.id!=='receipt-reason'&&e.target.id!=='confirm-human')dirty=true});
(async()=>{try{options=await api('/api/console/spec-templates/options');sample=options.sample;for(const p of [...options.users,...options.agents]){const o=document.createElement('option');o.value=p.id;o.label=p.name;$('principals').append(o)}const parents=await api('/api/console/spec-templates/parents');for(const p of parents.parents||[]){const o=document.createElement('option');o.value=p.spec_id;o.textContent=p.title+' · r'+p.revision;o.dataset.ref=JSON.stringify({spec_id:p.spec_id,revision:p.revision,content_sha256:p.content_sha256});$('parent').append(o)}await list();entries=[{id:'R1',kind:'requirement',fields:{}}];drawEntries();const params=new URLSearchParams(location.search),id=params.get('draft');if(id)await read(id);else if(params.get('predecessor_spec_id')){const id=params.get('predecessor_spec_id');const b=await api('/api/console/specs/'+encodeURIComponent(id));if(b.spec.state!=='final'||b.spec.archived||b.spec.principal_id!==options.actor_principal.replace(/^user:/,''))throw new Error('仅原 spec 所有者能创建未归档定稿的后继；代答权限不能改原文。');$('target').value=id;$('target-revision').value=b.spec.current_revision;$('predecessor').checked=true;$('title').value=b.spec.title+'（后继修订）';$('change-reason').closest('details').open=true;$('change-reason').focus();dirty=true;message('已绑定原定稿及版本；先填写变更理由与新范围，保存待确认草稿。原文与任务门仍保持。')}}catch(e){message(e.message)}})();
</script></html>`
